def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a recursive descent parsing technique.
    Handles strings, numbers, booleans, null, arrays, and objects.
    """
    index = 0

    def parse_value():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1

        if index >= len(s):
            raise ValueError("Unexpected end of input")

        char = s[index]

        if char == '"':
            return parse_string()
        elif char.isdigit() or (char == '-' and index + 1 < len(s) and s[index + 1].isdigit()):
            return parse_number()
        elif s.startswith("true", index):
            index += 4
            return True
        elif s.startswith("false", index):
            index += 5
            return False
        elif s.startswith("null", index):
            index += 4
            return None
        elif char == '[':
            return parse_array()
        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Invalid JSON value at index {index}")

    def parse_string():
        nonlocal index
        index += 1  # Skip the opening quote
        start = index
        while index < len(s):
            char = s[index]
            if char == '"':
                result = s[start:index]
                index += 1  # Skip the closing quote
                return result
            elif char == '\\':
                index += 1  # Skip the backslash
                if index < len(s):
                    index += 1  # Skip the escaped character
            else:
                index += 1
        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        num_str = s[start:index]
        try:
            return int(num_str) if '.' not in num_str else float(num_str)
        except ValueError:
            raise ValueError(f"Invalid number format at index {start}")

    def parse_array():
        nonlocal index
        index += 1  # Skip the opening bracket
        result = []
        while index < len(s):
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s) and s[index] == ']':
                index += 1  # Skip the closing bracket
                return result
            value = parse_value()
            result.append(value)
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s):
                if s[index] == ',':
                    index += 1  # Skip the comma
                elif s[index] == ']':
                    index += 1  # Skip the closing bracket
                    return result
                else:
                    raise ValueError(f"Expected ',' or ']' at index {index}")
        raise ValueError("Unterminated array")

    def parse_object():
        nonlocal index
        index += 1  # Skip the opening brace
        result = {}
        while index < len(s):
            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s) and s[index] == '}':
                index += 1  # Skip the closing brace
                return result

            key = parse_string()
            while index < len(s) and s[index].isspace():
                index += 1
            if index >= len(s) or s[index] != ':':
                raise ValueError(f"Expected ':' after key at index {index}")
            index += 1  # Skip the colon
            value = parse_value()
            result[key] = value

            while index < len(s) and s[index].isspace():
                index += 1
            if index < len(s):
                if s[index] == ',':
                    index += 1  # Skip the comma
                elif s[index] == '}':
                    index += 1  # Skip the closing brace
                    return result
                else:
                    raise ValueError(f"Expected ',' or '}' at index {index}")
        raise ValueError("Unterminated object")

    return parse_value()

def parse_json(s: str) -> object:
    """
    Parses a JSON string into Python objects using a state machine approach.
    This technique uses iterators to traverse the input string and handles different
    JSON constructs through state transitions based on the current character.
    """

    class State:
        INITIAL, STRING, NUMBER, TRUE, FALSE, NULL, ARRAY, OBJECT, KEY, AFTER_VALUE = range(9)

    def next_token():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1
        if index >= len(s):
            return None
        char = s[index]
        if char in '"[{,]}:':
            index += 1
            return char
        if char.isdigit() or (char == '-' and index + 1 < len(s) and s[index + 1].isdigit()):
            start = index
            index += 1
            while index < len(s) and (s[index].isdigit() or s[index] == '.'):
                index += 1
            return s[start:index]
        if s.startswith("true", index):
            index += 4
            return "true"
        if s.startswith("false", index):
            index += 5
            return "false"
        if s.startswith("null", index):
            index += 4
            return "null"
        return None

    def parse_string():
        nonlocal index
        if s[index] != '"':
            raise ValueError("Expecting string start")
        index += 1
        start = index
        while index < len(s):
            if s[index] == '"':
                result = s[start:index]
                index += 1
                return result
            if s[index] == '\\':
                index += 2  # Escape sequences: skip '\'
                continue
            index += 1
        raise ValueError("Unterminated string")

    index = 0
    stack = []
    current_state = State.INITIAL
    current_obj = None

    while True:
        token = next_token()
        if token is None and current_state == State.INITIAL:
            break
        if current_state == State.INITIAL:
            if token == '{':
                current_obj = {}
                stack.append(current_obj)
                current_state = State.OBJECT
            elif token == '[':
                current_obj = []
                stack.append(current_obj)
                current_state = State.ARRAY
            elif token:
                raise ValueError(f"Unexpected token: {token}")

        elif current_state == State.OBJECT:
            if token in (']', '}'):
                stack.pop()
                current_state = State.INITIAL if not stack else State.OBJECT
                if stack:
                    current_obj = stack[-1]
            elif token == '"':
                key = parse_string()
                token = next_token()
                if token != ':':
                    raise ValueError("Expected ':' after key")
                value = next_token()
                current_obj[key] = parse_value(value)
                current_state = State.AFTER_VALUE

        elif current_state == State.ARRAY:
            if token in (']', '}'):
                stack.pop()
                current_state = State.INITIAL if not stack else State.ARRAY
                if stack:
                    current_obj = stack[-1]
            elif token:
                value = parse_value(token)
                current_obj.append(value)
                current_state = State.AFTER_VALUE

        elif current_state == State.AFTER_VALUE:
            token = next_token()
            if token in (',', '}', ']'):
                current_state = State.OBJECT if token == '}' else State.ARRAY
            else:
                raise ValueError(f"Unexpected token after value: {token}")

    if stack:
        return stack[0]
    return current_obj

def parse_value(token):
    if token == "true":
