        elif char == '{':
            return parse_object()
        else:
            raise ValueError(f"Invalid JSON value at index {index-1}")

    def parse_string():
        str_buffer = []
        while True:
            char = next_char()
            if char == '"':
                return ''.join(str_buffer)
            elif char == '\\':
