        num_string = ''.join(num_buffer)
        if '.' in num_string or 'e' in num_string or 'E' in num_string:
            return float(num_string)
        return int(num_string)

    def parse_array():
        array = []
        char = next_char()
        while char is not None:
            while char.isspace():
                char = next_char()
            if char == ']':
                return array
            index -= 1
            array.append(parse_value())
            char = next_char()
            if char == ']':
                return array
            elif char != ',':
                raise ValueError("Expected ',' or ']' in array")

    def parse_object():
        obj = {}
        char = next_char()
        while char is not None:
            while char.isspace():
                char = next_char()
            if char == '}':
